import hashlib


def fingerprint(cert_der: bytes) -> str:
    """Compute the SHA-256 fingerprint of a certificate DER."""
    return hashlib.sha256(cert_der).hexdigest()


# Pre-defined pins for known hosts
_PIN_STORE = {
    "feeds.tessaro.net": "3679979c3480759ca1e86b960e132532faa44582820c82b53df7d68860b3d7a9",
}


class PinStore:
    @classmethod
    def load(cls):
        """Load the pin store from the feeds."""
        return cls()

    def matches(self, host: str, fp: str) -> bool:
        """Check if the fingerprint matches the pinned fingerprint for the host."""
        expected = _PIN_STORE.get(host)
        if expected is None:
            return False
        return expected == fp
